				\usepackage{amsbsy}
				\usepackage{mathrsfs}
				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$m_{e}=\frac{{mL}_{a}}{L_{c}}$$\end{document}me=mLaLc
